CREATE OR REPLACE FUNCTION sync_peoes_fazenda_id_on_acesso_id_update() RETURNS TRIGGER AS $$ BEGIN IF NEW.acesso_id IS DISTINCT FROM OLD.acesso_id THEN UPDATE peoes SET fazenda_id = NEW.acesso_id WHERE fazenda_id = OLD.acesso_id; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public; DROP TRIGGER IF EXISTS trg_sync_peoes_fazenda_id_on_acesso_id_update ON fazendas; CREATE TRIGGER trg_sync_peoes_fazenda_id_on_acesso_id_update AFTER UPDATE OF acesso_id ON fazendas FOR EACH ROW EXECUTE FUNCTION sync_peoes_fazenda_id_on_acesso_id_update();;
